import java.util.LinkedHashMap;
import model.Doctor;

/**
 * REPOSITORY dạng Singleton: cả chương trình chỉ có MỘT kho.
 */
public class DoctorRepository {

    // Bản duy nhất của kho. static vì nó thuộc về CLASS, không thuộc đối tượng nào
    private static DoctorRepository instance = null;

    // Dữ liệu thật — vẫn private, không ai chạm thẳng
    private LinkedHashMap<String, Doctor> doctorMap;

    // private constructor: chặn mọi lời gọi "new DoctorRepository()" từ bên ngoài
    private DoctorRepository() {
        doctorMap = new LinkedHashMap<>();
    }

    // Cửa duy nhất để lấy kho: lần đầu thì tạo, các lần sau trả lại đúng bản đó
    public static DoctorRepository getInstance() {
        // chưa có kho nào: tạo bản đầu tiên
        if (instance == null) {
            instance = new DoctorRepository();
        }

        return instance;
    }

    // Thêm bác sĩ dựng từ DTO — Repository nhận DTO, không bắt ai khác cầm Model
    public boolean addDoctor(DoctorRequestDTO requestDTO) {
        Doctor doctor = new Doctor(requestDTO.getCode(), requestDTO.getName(),
                requestDTO.getSpecialization(), requestDTO.getAvailability());

        // mã là khoá; true = đã thêm
        doctorMap.put(doctor.getCode(), doctor);
        return true;
    }
}

