package model;

/**
 * BUILDER: lắp một Doctor từng phần. KHÔNG static, KHÔNG kiểm tra dữ liệu (validate ở Main),
 * KHÔNG in.
 */
public class DoctorBuilder {

    // Thành phẩm đang lắp dở
    private Doctor doctor;

    // Bắt đầu với một bác sĩ rỗng (Doctor có constructor rỗng + setter như bài mẫu)
    public DoctorBuilder() {
        doctor = new Doctor();
    }

    // Đặt mã; trả về chính builder để nối tiếp lời gọi
    public DoctorBuilder setCode(String code) {
        doctor.setCode(code);
        return this;
    }

    // Đặt họ tên
    public DoctorBuilder setName(String name) {
        doctor.setName(name);
        return this;
    }

    // Đặt chuyên khoa
    public DoctorBuilder setSpecialization(String specialization) {
        doctor.setSpecialization(specialization);
        return this;
    }

    // Đặt số ca trực
    public DoctorBuilder setAvailability(int availability) {
        doctor.setAvailability(availability);
        return this;
    }

    // Giao thành phẩm
    public Doctor build() {
        return doctor;
    }
}

