            .setCode(requestDTO.getCode())
            .setName(requestDTO.getName())
            .setSpecialization(requestDTO.getSpecialization())
            .setAvailability(requestDTO.getAvailability())
            .build();

    // mã là khoá; true = đã thêm
    doctorMap.put(doctor.getCode(), doctor);
    return true;
}

