package service;

import java.util.ArrayList;
import model.Doctor;

/**
 * STRATEGY: "biết cách sắp xếp một danh sách bác sĩ". Interface bắt đầu bằng "I" (mục 1.3).
 */
public interface ISortStrategy {

    // Sắp xếp danh sách tại chỗ
    void sort(ArrayList<Doctor> doctorList);
}

// ===== service/NameSortStrategy.java — mỗi cách sắp xếp = một class, tên là DANH TỪ =====
package service;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import model.Doctor;

/**
 * Tên A-Z, không phân biệt hoa thường (mục 3.5).
 */
public class NameSortStrategy implements ISortStrategy {

    // Sắp theo tên, bỏ qua hoa/thường
    @Override
    public void sort(ArrayList<Doctor> doctorList) {
        Collections.sort(doctorList,
                Comparator.comparing(Doctor::getName, String.CASE_INSENSITIVE_ORDER));
    }
}

// ===== service/AvailabilitySortStrategy.java =====
package service;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import model.Doctor;

/**
 * Nhiều ca trực lên trước.
 */
public class AvailabilitySortStrategy implements ISortStrategy {

    // Sắp theo số ca trực, giảm dần
    @Override
    public void sort(ArrayList<Doctor> doctorList) {
        Collections.sort(doctorList,
                Comparator.comparingInt(Doctor::getAvailability).reversed());
    }
}

