package service;

import constants.Constants;
import java.util.ArrayList;

/**
 * Ghi lịch sử vào bộ nhớ. KHÔNG in — ai cần xem thì hỏi qua Services, kết quả đi Controller -> View.
 */
public class HistoryObserver implements IDoctorObserver {

    // Mỗi thao tác một dòng, theo thứ tự xảy ra (mục 1.5: tên kết thúc bằng List)
    private ArrayList<String> historyList;

    // Bắt đầu với lịch sử rỗng
    public HistoryObserver() {
        historyList = new ArrayList<>();
    }

    // Ghi thêm một dòng "ADD: D01"; định dạng nằm ở Constants (mục 2.10)
    @Override
    public void update(String action, String code) {
        historyList.add(String.format(Constants.HISTORY_FORMAT, action, code));
    }

    // Trả BẢN SAO lịch sử để Services đưa vào ResponseDTO
    public ArrayList<String> getHistoryList() {
        return new ArrayList<>(historyList);
    }
}

